import re

def validateAspectRatio(aspectRatio):
    pattern = r'^(\d+):(\d+)$'
    match = re.match(pattern, aspectRatio)
    if match:
        width = int(match.group(1))
        height = int(match.group(2))
        if width >= 640 and height >= 480:
            return True
    return False

