import subprocess

def stream_pod_logs():
    try:
        # Use subprocess to execute the kubectl command and capture the output
        pod_name_cmd = "kubectl get pod -l app=productpage -o jsonpath='{.items[0].metadata.name}'"
        pod_name_process = subprocess.Popen(pod_name_cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        pod_name_output, pod_name_error = pod_name_process.communicate()

        if pod_name_process.returncode != 0:
            raise Exception(f"Error retrieving pod name: {pod_name_error.decode('utf-8')}")

        pod_name = pod_name_output.decode('utf-8').strip()

        # Stream the logs of the istio-proxy container within the retrieved pod
        logs_cmd = f"kubectl logs -f {pod_name} -c istio-proxy"
        logs_process = subprocess.Popen(logs_cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        logs_output, logs_error = logs_process.communicate()

        if logs_process.returncode != 0:
            raise Exception(f"Error streaming pod logs: {logs_error.decode('utf-8')}")

        return logs_output.decode('utf-8')
    except Exception as e:
        return f"Error: {str(e)}"

